begin;
do $$
declare u uuid:=gen_random_uuid(); other_u uuid:=gen_random_uuid(); a uuid; b uuid; foreign_a uuid;
 j text:='planner-'||gen_random_uuid(); j2 text:='planner-'||gen_random_uuid(); result jsonb;
 h text:=md5(gen_random_uuid()::text)||md5(gen_random_uuid()::text); s uuid:=gen_random_uuid(); targets jsonb; stale jsonb;
begin
 insert into auth.users(id) values(u),(other_u);
 insert into public.jobs(id,canonical_url,employer) values(j,'https://example.com/planner/one','{"company":"One Systems","title":"Database Engineer"}'),(j2,'https://example.com/planner/two','{"company":"Two Systems","title":"Database Engineer"}');
 insert into public.applications(user_id,job_id,draft) values(u,j,'{}') returning id into a;
 insert into public.applications(user_id,job_id,draft) values(u,j2,'{}') returning id into b;
 insert into public.applications(user_id,job_id,draft) values(other_u,j,'{}') returning id into foreign_a;
 insert into public.preparation_plans(user_id,application_id,plan) values(u,a,jsonb_build_object('applicationId',j,'tasks','[{"id":"practice","minutes":30,"completed":false}]'::jsonb)),(u,b,jsonb_build_object('applicationId',j2,'tasks','[{"id":"practice","minutes":30,"completed":false}]'::jsonb)),(other_u,foreign_a,'{"tasks":[{"id":"practice","minutes":30,"completed":false}]}');
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Planner tests',h,array['workspace:read','preferences:write','drafts:write'],now()+interval '1 hour');
 perform set_config('test.uid',u::text,true);
 execute 'set local role authenticated';
 result:=public.read_preparation_planner();
 if jsonb_array_length(result->'plans')<>2 or (result->'settings'->>'dailyMinutes')::integer<>45 or (select count(*) from jsonb_object_keys(result->'applications'))<>2 then raise exception 'Planner snapshot missing or leaks owner'; end if;
 result:=public.save_preparation_budget(30,0);
 if result->'settings'->>'version'<>'1' then raise exception 'Budget version missing'; end if;
 begin perform public.save_preparation_budget(90,0);raise exception 'Stale budget allowed';exception when serialization_failure then null;end;
 begin perform public.save_preparation_budget(241,1);raise exception 'Unbounded budget allowed';exception when invalid_parameter_value then null;end;
 targets:=jsonb_build_array(jsonb_build_object('applicationId',a,'taskId','practice','expectedVersion',1),jsonb_build_object('applicationId',b,'taskId','practice','expectedVersion',1));
 result:=public.complete_preparation_session(s,15,targets);
 if jsonb_array_length(result->'sessions')<>1 or (select count(*) from public.preparation_plans where version=2)<>2 or exists(select 1 from public.preparation_plans where plan->'tasks'->0->>'completed'='true') then raise exception 'Partial practice credit incorrect';end if;
 result:=public.complete_preparation_session(s,15,targets);
 if jsonb_array_length(result->'sessions')<>1 or (select count(*) from public.preparation_plans where version=2)<>2 then raise exception 'Retry double counted';end if;
 begin perform public.complete_preparation_session(s,10,targets);raise exception 'Conflicting session replay allowed';exception when invalid_parameter_value then null;end;
 stale:=jsonb_build_array(jsonb_build_object('applicationId',a,'taskId','practice','expectedVersion',2),jsonb_build_object('applicationId',b,'taskId','practice','expectedVersion',1));
 begin perform public.complete_preparation_session(gen_random_uuid(),15,stale);raise exception 'Stale grouped completion allowed';exception when serialization_failure then null;end;
 if (select count(*) from public.preparation_sessions)<>1 or (select count(*) from public.preparation_plans where version=2)<>2 then raise exception 'Stale write partly committed';end if;
 begin perform public.complete_preparation_session(gen_random_uuid(),15,jsonb_build_array(jsonb_build_object('applicationId',foreign_a,'taskId','practice','expectedVersion',1)));raise exception 'Foreign completion allowed';exception when no_data_found then null;end;
 targets:=jsonb_build_array(jsonb_build_object('applicationId',a,'taskId','practice','expectedVersion',2),jsonb_build_object('applicationId',b,'taskId','practice','expectedVersion',2));
 result:=public.complete_preparation_session(gen_random_uuid(),15,targets);
 if (select count(*) from public.preparation_plans where version=3 and plan->'tasks'->0->>'completed'='true')<>2 or (select sum(minutes) from public.preparation_sessions)<>30 then raise exception 'Shared session did not complete both tasks once';end if;
 begin perform public.complete_preparation_session(gen_random_uuid(),1,targets);raise exception 'Budget overrun allowed';exception when invalid_parameter_value then null;end;
 begin update public.preparation_sessions set minutes=1;raise exception 'Ledger rewrite allowed';exception when insufficient_privilege then null;end;
 begin perform private.preparation_budget_owned(other_u,20,0);raise exception 'Private owner RPC callable';exception when insufficient_privilege then null;end;
 perform set_config('test.uid',other_u::text,true);
 if (select count(*) from public.preparation_sessions)<>0 or (select count(*) from public.preparation_planner_settings)<>0 then raise exception 'Foreign planner state visible';end if;
 execute 'reset role';
 result:=public.agent_dispatch(h,'preparation.planner.read','{}');
 if jsonb_array_length(result->'sessions')<>2 then raise exception 'Agent snapshot differs from website';end if;
 result:=public.agent_dispatch(h,'preparation.budget','{"dailyMinutes":60,"expectedVersion":1}');
 if result->'settings'->>'dailyMinutes'<>'60' then raise exception 'Agent budget did not use shared service';end if;
 -- Retry the same session through MCP; it must remain idempotent after versions move.
 result:=public.agent_dispatch(h,'preparation.session.complete',jsonb_build_object('sessionId',s,'minutes',15,'targets',jsonb_build_array(jsonb_build_object('applicationId',a,'taskId','practice','expectedVersion',1),jsonb_build_object('applicationId',b,'taskId','practice','expectedVersion',1))));
 if jsonb_array_length(result->'sessions')<>2 then raise exception 'Agent retry double counted';end if;
 update private.agent_connections set scopes=array['workspace:read'] where token_hash=h;
 begin perform public.agent_dispatch(h,'preparation.budget','{"dailyMinutes":90,"expectedVersion":2}');raise exception 'Budget scope bypass';exception when insufficient_privilege then null;end;
 begin perform public.agent_dispatch(h,'preparation.session.complete',jsonb_build_object('sessionId',gen_random_uuid(),'minutes',10,'targets',targets));raise exception 'Session scope bypass';exception when insufficient_privilege then null;end;
 execute 'set local role anon';
 begin perform public.read_preparation_planner();raise exception 'Anonymous planner access';exception when insufficient_privilege then null;end;
 execute 'reset role';
end $$;
rollback;
